#!/usr/bin/env bash
# Gets everything ready for the presentation (see presentation/1-Before-the-presentation.html).
# Generated by scripts/presentation/pages.js from content.js.
cd "$(dirname "$0")/../.." || exit 1
step() { printf '\n\033[1m▶ %s\033[0m\n  %s\n' "$1" "$2"; }
fail=0

echo; echo "=== 1/6: Go to the project, on the correct code ==="
step "git checkout main && git pull" "Switches to the correct code and fetches the latest version from GitHub."
git checkout main || { echo "  ✗ step failed"; fail=1; }
git pull --ff-only || echo "  (git pull skipped: offline or no upstream)"
step "git status" "Should say \"nothing to commit, working tree clean\"."
git status || { echo "  ✗ step failed"; fail=1; }

echo; echo "=== 2/6: Warm up the build and confirm everything is green ==="
step "make ios-test" "Builds the project and runs all screenshot and logic tests (1–2 min the first time). Must end with \"no snapshot failures\". After this, the live run on slide 4 takes ~40 s."
make ios-test || { echo "  ✗ step failed"; fail=1; }

echo; echo "=== 3/6: Warm up the regression demo (it fails on purpose) ==="
step "git checkout demo/regression && make ios-test ; git checkout main" "Builds the bug branch once, so the live demo on slide 6 is quick. It fails on purpose (29 failures); the last part switches back to main."
git checkout demo/regression && make ios-test ; git checkout main
echo "  (the failure above is expected: it's the deliberate regression)"

echo; echo "=== 4/6: Build the page you'll open on slide 5 ==="
step "make gallery" "Creates artifacts/gallery/index.html: every golden on one page."
make gallery || { echo "  ✗ step failed"; fail=1; }

echo; echo "=== 5/6: Start the simulator with the app ==="
step "make ios-run" "Builds the app, boots the pinned simulator and opens it (first time ~1.5 min). After this, ios-run on slide 9 takes ~15 s."
make ios-run || { echo "  ✗ step failed"; fail=1; }

echo; echo "=== 6/6: Open the windows you'll switch between ==="
step "open -a \"Visual Studio Code\" ." "Opens the project in VS Code, so files open instantly during the talk."
open -a "Visual Studio Code" . || { echo "  ✗ step failed"; fail=1; }
step "open https://github.com/SaadiIftikhar/newsdemo-screenshot-testing/pull/1 https://github.com/SaadiIftikhar/newsdemo-screenshot-testing/pull/2 https://github.com/SaadiIftikhar/newsdemo-screenshot-testing/actions" "Opens the browser tabs for slides 7 and 11."
open https://github.com/SaadiIftikhar/newsdemo-screenshot-testing/pull/1 https://github.com/SaadiIftikhar/newsdemo-screenshot-testing/pull/2 https://github.com/SaadiIftikhar/newsdemo-screenshot-testing/actions || { echo "  ✗ step failed"; fail=1; }
step "open presentation/Presentation.pptx" "Opens the deck in PowerPoint."
open presentation/Presentation.pptx || { echo "  ✗ step failed"; fail=1; }

git checkout -q main
echo
echo "=== Done. Branch: $(git branch --show-current) ==="
[ "$fail" = 0 ] && echo "All steps passed. You're ready." || echo "Some step failed: scroll up for ✗ before presenting."
